<?php
declare(strict_types=1);namespace Atlas\Platform\Resources\Sources;use Atlas\Platform\Organizations\Services\CurrentOrganizationResolver;final class SourceWorkspaceAdminPage{private string$hook='';public function __construct(private SourceWorkspaceRepository$repo,private CurrentOrganizationResolver$orgs){}public function register():void{$this->hook=(string)add_submenu_page('atlas',__('Sources','atlas-platform'),__('Sources','atlas-platform'),'atlas_upload_sources','atlas-sources',[$this,'render']);}public function enqueue(string$hook):void{if($hook===$this->hook){wp_enqueue_style('atlas-preview',ATLAS_PLATFORM_URL.'assets/css/atlas-preview.css',[],ATLAS_PLATFORM_VERSION);}}public function createDocument():void{$this->guard('atlas_upload_sources','atlas_create_source_document');$org=$this->orgs->resolveForUser(get_current_user_id());$this->repo->createDocument($org?->id,get_current_user_id(),wp_unslash($_POST));$this->redirect();}public function updateDocumentStatus():void{$this->guard('atlas_upload_sources','atlas_update_source_status');$org=$this->orgs->resolveForUser(get_current_user_id());$this->repo->updateDocumentStatus(sanitize_text_field(wp_unslash((string)($_POST['source_document_id']??''))),$org?->id,sanitize_key(wp_unslash((string)($_POST['status']??''))),sanitize_textarea_field(wp_unslash((string)($_POST['notes']??''))));$this->redirect();}public function createSection():void{$this->guard('atlas_upload_sources','atlas_create_source_section');$this->repo->createSection(sanitize_text_field(wp_unslash((string)($_POST['source_document_id']??''))),wp_unslash($_POST));$this->redirect();}public function createCandidate():void{$this->guard('atlas_review_extractions','atlas_create_extraction_candidate');$org=$this->orgs->resolveForUser(get_current_user_id());$this->repo->createCandidate(sanitize_text_field(wp_unslash((string)($_POST['source_section_id']??''))),$org?->id,wp_unslash($_POST));$this->redirect();}public function reviewCandidate():void{$this->guard('atlas_review_extractions','atlas_review_extraction_candidate');$this->repo->reviewCandidate(sanitize_text_field(wp_unslash((string)($_POST['candidate_id']??''))),sanitize_key(wp_unslash((string)($_POST['status']??''))),get_current_user_id());$this->redirect();}public function createRequirement():void{$this->guard('atlas_review_extractions','atlas_create_payer_requirement');$org=$this->orgs->resolveForUser(get_current_user_id());$this->repo->createRequirement($org?->id,get_current_user_id(),wp_unslash($_POST));$this->redirect();}public function reviewRequirement():void{$this->guard('atlas_review_extractions','atlas_review_payer_requirement');$org=$this->orgs->resolveForUser(get_current_user_id());$this->repo->reviewRequirement(sanitize_text_field(wp_unslash((string)($_POST['requirement_id']??''))),$org?->id,sanitize_key(wp_unslash((string)($_POST['status']??''))),get_current_user_id());$this->redirect();}public function render():void{$this->guard('atlas_upload_sources','');$org=$this->orgs->resolveForUser(get_current_user_id());$criteria=['payer'=>sanitize_text_field(wp_unslash((string)($_GET['payer']??''))),'topic'=>sanitize_text_field(wp_unslash((string)($_GET['topic']??''))),'status'=>sanitize_key(wp_unslash((string)($_GET['status']??'')))];$summary=$this->repo->summary($org?->id);$documents=$this->repo->documents($org?->id);$candidates=$this->repo->candidates($org?->id);$requirements=$this->repo->requirements($org?->id,50,$criteria);require ATLAS_PLATFORM_DIR.'templates/resources/sources.php';}private function guard(string$cap,string$nonce):void{if(!current_user_can($cap)){wp_die(esc_html__('Not allowed.','atlas-platform'),'', ['response'=>403]);}if($nonce!==''){check_admin_referer($nonce);}}private function redirect():never{wp_safe_redirect(admin_url('admin.php?page=atlas-sources'));exit;}}
